{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "web" });
  const eligible = issues.filter((i) => i.count >= 0);
  const out: { shortId: string; count: number; status: string; latestRelease: string | null }[] = [];
  for (const issue of eligible) {
    let events: { id: string; issueId: string; timestamp: string; release: string; message: string }[] = [];
    try {
      const res = await sdk.sentry.listIssueEvents({ issueId: issue.id });
      events = res.events ?? [];
    } catch (e) {
      events = [];
    }
    let latest: string | null = null;
    if (events.length > 0) {
      const sorted = [...events].sort((a, b) => Date.parse(b.timestamp) - Date.parse(a.timestamp));
      const rel = sorted[0]?.release;
      latest = rel && rel.length > 0 ? rel : null;
    }
    out.push({ shortId: issue.shortId, count: issue.count, status: issue.status, latestRelease: latest });
  }
  out.sort((a, b) => b.count - a.count);
  return { total: issues.length, eligible: eligible.length, rows: out };
}", "input": {}}

{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "web" });
  const detail = [];
  for (const issue of issues) {
    let events: any[] = [];
    let err: string | null = null;
    try {
      const res = await sdk.sentry.listIssueEvents({ issueId: issue.id });
      events = res.events ?? [];
    } catch (e) {
      err = String(e);
    }
    detail.push({ id: issue.id, shortId: issue.shortId, count: issue.count, status: issue.status, project: issue.project, err, events });
  }
  return detail;
}", "input": {}}
